#!/usr/bin/env bash
# B4c = B2f with ONE factor changed: + --aug_dtx_p 0.3 (webrtcvad DTX gating on 30% of clips; --aug_dtx_fill left at default mix)
#   generated by exploop (wave B4, iteration 3) from exploop/B4/iter03/design.result.json
#  B4c = B2f + --aug_dtx_p 0.3 (dtx_gate arm, iteration c of the B4 screen; rdloop B4 module
#    b4wave). On 30% of training clips (separate B4 RNG stream, both classes), webrtcvad gates the
#    audio after the NS slot and before the codec. Mode 1-3 and frame 10/20/30 ms are drawn per
#    clip, with a forward hangover of 40-200 ms. Gated frames are filled with digital zeros or
#    order-10 LPC comfort noise, 50/50 per clip (--aug_dtx_fill mix, default of the coupled flag).
#    Target: the saturated noisy bona false alarms that remain after B4a/B4b. The B4b report counts
#    210 / 202 of 782 half-B noisy bona as false alarms, 55% / 67% at p >= 0.99; half-B saturated
#    FA are 136 / 133 on B2f. On the full set (final) they concentrate in pause-rich source clips
#    (pinned tertiles 66 / 76 / 107). sil_only bona are 100% spoof, and offline VAD-gated heldout
#    bona trail ungated bona (B2f final recall 66.2 vs 73.6). Placebos: B4a (VAD DiD -0.22 / -0.54,
#    criterion (ii) +10) and B4b (VAD DiD +0.36 / +0.22, ANOMALOUS z +3.82 / +4.25, criterion (ii)
#    +2). The lever is under-dosed as built (dose ratio ~0.027), so a null reads 'inconclusive
#    (under-dosed)'. Everything else is B2f's argv, 8 epochs, batch 16, seed 1234.
#  Why: This is the pre-registered iteration c of the B4 screen. wave.json lever_notes say
#    "iterations a-c are the queued arms in this order, apm_ns -> opus_plc -> dtx_gate, each
#    exactly its `set` on top of B2f's argv". plan_snapshot.md row c is `dtx_gate` `--aug_dtx_p
#    0.3`. In the owner decisions at the handoff, the dtx_gate under-dose is accepted and the arm
#    "runs last as a placebo arm". The B4b analyst ranks this arm first (analyze.result.json, rank
#    1). user_notes.md has one note. It only re-labels B4a's decisions (merge revisit, final
#    promote) and does not change the queue. Base = B2f, because rules.keep_best keeps B2f as the
#    reference for the whole wave. Neither B4a's nor B4b's flag is carried over. Evidence for the
#    target. The B4b report gives the largest remaining error as confident noisy heldout bona false
#    alarms: 210 / 202 of the 782 half-B noisy bona are false alarms (merge / final), 55% / 67% of
#    them at p >= 0.99. A global threshold recovers only 0.03 / 0.13 of the 0.25 / 0.24 oracle gap,
#    so this is a ranking problem. The dtx_gate lever targets the part of that saturated core that
#    the plan ties to gated or non-speech content: - half-B saturated FA (p >= 0.99) are 136 / 133
#    on B2f; - on the full set (final) they concentrate in the pause-rich tertile: B2f 66 / 76 /
#    107, low / mid / high; - sil_only bona are 100% spoof (B2f mean dP +0.8929 / +0.8985), and
#    noise_only bona are 99.47-100% spoof; - offline VAD-gated heldout bona trail ungated bona: B2f
#    final recall T/C 66.2 / 73.6. B4b strengthens the case for running this arm. It never gated a
#    frame, yet it moved VAD-gated heldout bona toward spoof: VAD DiD +0.36 / +0.22, z +3.82 /
#    +4.25, flagged ANOMALOUS (O3.1). So the VAD slice is sensitive to training-side DSP. B4a moved
#    it the other way (-0.22 / -0.54). Both arms now serve as placebos for this contrast. No other
#    configuration lever has a stronger claim on this slot. The apm_ns dose step (analyst rank 2)
#    and the opus zero-loss control (rank 3) are candidates for the conditional iteration d.
#    opus_plc was not positive (verdict null on both readouts), so the plan's automatic d control
#    is not triggered. A seed repeat is not needed while this pre-registered configuration arm is
#    untested. Constraints: - One factor: `--aug_dtx_p` belongs to the coupled group [--aug_dtx_p,
#    --aug_dtx_fill]. `--aug_dtx_fill` stays at its default `mix` (50/50 zero / LPC comfort-noise
#    fill per clip), as the plan specifies. - The flag is in `allowed`, nothing forbidden is
#    touched and the fixed flags are unchanged. - num_epochs stays 8 (max 10) and batch_size 16,
#    per the plan. - validate_b4_args only checks 0 <= p <= 1. _init_dtx_gate needs only a valid
#    fill plus webrtcvad and the selftest, and has no codec-profile precondition. - The lever runs
#    in the post_dsp slot after NS (off here) and before the codec, from the separate B4 RNG
#    stream, so the B2f draws are otherwise untouched. Known caveat (lever_notes): dtx_gate is
#    under-dosed as built (dose ratio ~0.027 vs the 0.25 rule). A null therefore reads
#    "inconclusive (under-dosed)", never "refuted". The arm still counts as a placebo for the NS
#    and PLC contrasts at the wave SUMMARY.
#  Hypothesis: Part of the saturated noisy-bona false-alarm core is the shortcut "gated or
#    non-speech content => spoof". B2f never trained on DTX-style gated pauses, so it reads them as
#    synthesis. On the full set (final), saturated noisy bona FA rise with the source clip's
#    non-speech share (66 / 76 / 107 by pinned tertile). Every null-panel run shows the same
#    concentration (criterion (ii) panel mean -10.2, max 0), so it is a property of the model
#    family. sil_only bona are 100% spoof, and offline VAD-gated heldout bona trail ungated bona
#    (66.2 vs 73.6 final). B4c gates 30% of training clips of both classes with webrtcvad (mode
#    1-3, 10/20/30 ms frames, 40-200 ms hangover) and fills the gated frames with digital zeros or
#    order-10 LPC comfort noise (mix). This should make gated pauses class-neutral: pause-rich bona
#    leaves the saturated tail, the VAD-gated heldout slice moves toward bona, and the sil_only /
#    noise_only probes lose spoof confidence. Spoof recall should hold, because the gating is
#    applied the same way to both classes.
#  Expected signature: Mechanism (scripts/b4_dsp_slices.py --lever dtx_gate, --ref = B2f's same
#    readout, --placebo = B4a and B4b; full set, final primary). Both of the following are needed:
#    - (ii) Anchor: saturated-FA (p >= 0.99) drop_high - drop_low >= +5 clips (pinned cuts; B2f 107
#    vs 66) and above both placebos (B4a +10, B4b +2), plus >= 0 on half B for both readouts (B4b
#    had -11 final / -3 merge). - (i') VAD contrast at least directional: DiD < -0.57 (panel mu
#    -0.57, sd 0.24) and below B4a's -0.22 (final) / -0.54 (merge) and B4b's +0.36 / +0.22.
#    'Strong' (not required) means VAD DiD <= -1.05 with CI upper < -0.57. Report the VAD split by
#    fill. A gain confined to vad:zero (zero-fill DiD* <= -0.42 with CNG-fill DiD* >= 0) is
#    near-in-distribution; transfer needs CNG-fill DiD < -0.38. Outcome: - sil_only bona mean dP
#    below +0.8929 (merge) / +0.8985 (final); - noise_only bona below the 99.47-100% spoof range; -
#    half-B saturated noisy bona FA down from 136 / 133; - offline VAD-gated heldout bona recall up
#    from 66.2 (final); - expected half_B WF1 delta vs B2f (91.98 / 92.14) of 0 to +0.5. Must not
#    move: - dev_online_clean F1 within 0.5 of 97.60 / 97.69; - half-B noisy spoof misses <= 36 /
#    35; - full-set offline-VAD spoof misses <= 25 / 22; - probe_padded bona flip up by at most 2
#    clips from 3.74 / 5.35%; - R_spoof within 0.5 on every set; - ep1 TrainAcc within 2 of 87.36.
#    Train log: the 'Epoch N B3 aug' / 'B4 aug-by-class' lines should show wrtc_dtx_zero +
#    wrtc_dtx_cng near 0.3 x 75,785 clips per epoch (about 22,736; bona about 4,306, spoof about
#    18,430), split roughly evenly between zero and cng, with the dtx_g* gated-fraction bins
#    populated and fail_wrtc_dtx near 0.
#  Derivation: python3 -I -c "n_b,n_s=14353,61432; ..." (clip counts from B4b logs/train.log 'Epoch
#    1 B4 aug-by-class'): clips/epoch 75785 expected dtx clips 0.3*n = 22736 (bona 4306 , spoof
#    18430 ); fill=mix -> ~half zero / half cng each ~ 11368
#  Eval note: Screen arm. B2f stays the reference (rules.keep_best). Compare both readouts
#    (merge_top5, epoch_8) with B2f-top5 / B2f-ep8 on the 17 sls_local17 sets with a 2000-sample
#    bootstrap CI. Run scripts/b4_dsp_slices.py --lever dtx_gate on merge and final with --ref =
#    B2f's same readout and --placebo = B4a and B4b. This is the first arm with 2 placebos. B4a's
#    VAD DiD is -0.22 / -0.54 and its criterion (ii) is +10; B4b's VAD DiD is +0.36 / +0.22
#    (ANOMALOUS) and its criterion (ii) is +2. Report the pinned non-speech tertiles (full set and
#    half B, both readouts), the VAD contrast split by fill (zero vs cng), the sil_only /
#    noise_only / probe_padded bona probes, and half-B saturated FA (B2f 136 / 133). Check that the
#    arm is not ANOMALOUS on the non-target NS and PLC contrasts. It is a placebo for apm_ns and
#    opus_plc at the wave SUMMARY. Apply the under-dose rule: a null is 'inconclusive
#    (under-dosed)'. Watch the spoof-miss guards (half-B noisy <= 36 / 35, VAD <= 25 / 22),
#    dev_online_clean F1, and the wrtc_dtx_* / dtx_g* / fail_wrtc_dtx counts in train.log.
#  Falsification (pre-registered): delta top-5-merge half_B.wf1.wf1 vs B2f merge (91.98) > +0.5
#    with the paired-bootstrap CI excluding 0 and clean F1 drop <= 0.5 -> positive; within +-0.5 ->
#    null; below -0.5 -> negative. (1) Mechanism not supported: VAD DiD >= -0.57 AND drop_high -
#    drop_low <= -10.2 on the full set, final, with half_B WF1 delta < +0.5. Under the README dose
#    rule this reads 'inconclusive (under-dosed)', never 'refuted'. (2) Guard break:
#    dev_online_clean F1 down > 0.5, half-B noisy spoof misses > 36 / 35, or full-set offline-VAD
#    spoof misses > 25 / 22. The gating then carries class information, so drop. (3) Shared
#    under-fit: ep1 TrainAcc < 85.36 or ep8 TrainLoss > 0.0752, together with heldout bona recall
#    down. Drop. (4) Criterion (ii) passes (>= +5) but stays at or below B4a's placebo +10: not
#    specific to gating, at most 'directional'. (5) A high fail_wrtc_dtx count, or wrtc_dtx counts
#    far from ~0.3 of the clips: confounded (not dosed as designed). Verdict rule: positive = merge
#    half_B WF1 delta > +0.5 with CI low > 0 and clean drop <= 0.5; |delta| <= 0.5 = null.
#
#   bash scripts/run_B4c.sh                                   # fresh run (the exploop supervisor launches it)
#   bash scripts/run_B4c.sh --resume exp/<run dir name>       # after a container restart
#   EXPLOOP_PRINT_ARGV=1 bash scripts/run_B4c.sh              # print the trainer argv, launch nothing
#
# Rendered from scripts/exploop/launcher_template.sh (same shape as scripts/run_B3a.sh). Extra
# arguments are appended to the trainer command line. Training runs under nohup; stdout/stderr go to
# <workdir>/<track>_<timestamp>.log and the per-epoch summary to <run dir>/logs/train.log.
set -euo pipefail

PY="${PY:-/root/.conda/envs/rtc-sdd/bin/python}"
TRACK="B4c_qwen17_rtc_musan_loud23_cos8_lr2.5e6_dtx03_s1234"
WORKDIR="/root/repos/rtc-sdd/Ghostbusters_team/SLS_setup"

ARGS=(
    --train_data_path /mnt/paml-research/RTCFake/data/wav/train
    --train_protocol /mnt/paml-research/RTCFake/data/train_label.txt
    --dev_data_path /mnt/paml-research/RTCFake/data/wav/dev
    --dev_protocol ../data/dev_noisy_sim/dev_label_excl_halfB.txt
    --ssl_name Qwen/Qwen3-ASR-1.7B
    --n_layers 24
    --batch_size 16
    --num_epochs 8
    --num_workers 64
    --use_rtc_aug
    --aug_noise_dirs ../data/augmentation_train/rnnoise ../data/augmentation_train/esc50
    --aug_rir_dirs ../data/augmentation_train/rirs
    --musan
    --musan_dir ../data/augmentation/musan
    --loudness_norm
    --loudness_norm_lufs -23
    --optim adamw
    --lr 2.5e-6
    --head_lr_mult 10
    --weight_decay 0.01
    --lr_scheduler warmup_cosine
    --warmup_frac 0.05
    --lr_min 5e-7
    --grad_clip 1.0
    --ema_decay 0.9995
    --local_eval_sets ../configs/local_eval_sets.yaml
    --earlystop_metric wf1
    --earlystop_epoch 99
    --keep_topk_by_wf1 7
    --keep_epochs 8
    --seed 1234
    --track "$TRACK"
    --aug_dtx_p 0.3
)

if [ "${EXPLOOP_PRINT_ARGV:-0}" = "1" ]; then
    printf '%s\n' "${ARGS[@]}"
    exit 0
fi

if [ ! -x "$PY" ]; then
    echo "python not found: $PY (set PY=... to override)" >&2
    exit 1
fi
if ! command -v ffmpeg >/dev/null 2>&1; then
    echo "ffmpeg not found on PATH: the RTC codec augmentation would silently no-op. Reinstall it first." >&2
    exit 1
fi
if ! "$PY" -c "import pyloudnorm" >/dev/null 2>&1; then
    echo "pyloudnorm not importable by $PY: run '$PY -m pip install pyloudnorm==0.2.0' first." >&2
    exit 1
fi

cd "$WORKDIR"
LOG="${TRACK}_$(date +%Y%m%d%H%M%S).log"

nohup "$PY" -u -m b4wave.train "${ARGS[@]}" "$@" > "$LOG" 2>&1 &

PID=$!
echo "Started $TRACK (pid $PID)"
echo "Log:     $WORKDIR/$LOG"
echo "Follow:  tail -f $WORKDIR/$LOG"
echo "Stop:    kill $PID"
